// Generated by Cypress Author on 2026-11-05
/**
 * ux-20-dnd-visual-parity-and-no-overlap.cy.js
 *
 * End-to-end Cypress test verifying:
 * 1. Ghost preview renders at 100% 1:1 real size without artificial clamping, scale down, or rotation.
 * 2. Visual drop indicator ('sombra') reserves exact space with 0.35 opacity and dashed outline.
 * 3. Zero text overlap: dragged placeholder and sibling sections never share bounding coordinates.
 * 4. Midpoint cursor detection: hovering top 50% vs bottom 50% selects above vs below.
 * 5. Atomic drop commit commits the new order cleanly.
 */

describe('UX Test 20: Drag and Drop 1:1 Scale Parity & Zero Overlap Verification', () => {
  beforeEach(() => {
    cy.visit('/');
    cy.waitForFonts();
    cy.get('#area-cv').should('be.visible');

    // Dismiss tour modal/popover if present
    cy.get('body').then(($body) => {
      const skipBtn = $body.find('button:contains("Omitir"), button:contains("Saltar")');
      if (skipBtn.length > 0) {
        cy.wrap(skipBtn.first()).click({ force: true });
        cy.wait(200);
      }
    });
  });

  const simulateDrag = ($handle, targetX, targetY) => {
    const handleRect = $handle[0].getBoundingClientRect();
    const startX = Math.round(handleRect.left + handleRect.width / 2);
    const startY = Math.round(handleRect.top + handleRect.height / 2);

    // 1. PointerDown on handle
    cy.wrap($handle).trigger('pointerdown', {
      pointerId: 1,
      pointerType: 'mouse',
      isPrimary: true,
      button: 0,
      buttons: 1,
      which: 1,
      clientX: startX,
      clientY: startY,
      bubbles: true,
      cancelable: true,
      force: true,
    });

    // 2. Incremental PointerMoves into target coordinates
    const steps = 10;
    for (let i = 1; i <= steps; i++) {
      const curX = Math.round(startX + ((targetX - startX) * i) / steps);
      const curY = Math.round(startY + ((targetY - startY) * i) / steps);
      cy.document().trigger('pointermove', {
        pointerId: 1,
        pointerType: 'mouse',
        isPrimary: true,
        button: 0,
        buttons: 1,
        which: 1,
        clientX: curX,
        clientY: curY,
        bubbles: true,
        cancelable: true,
      });
    }
  };

  const endDrag = (endX, endY) => {
    cy.document().trigger('pointerup', {
      pointerId: 1,
      pointerType: 'mouse',
      isPrimary: true,
      button: 0,
      buttons: 0,
      clientX: endX,
      clientY: endY,
      bubbles: true,
      cancelable: true,
    });
  };

  it('Drag Section → Ghost preview renders at 1:1 scale with realistic styling and zero distortion', () => {
    cy.get('#projects, #experience, [data-section-id="projects"], [data-section-id="experience"]')
      .first()
      .as('targetSection');

    cy.get('@targetSection').should('be.visible').then(($sec) => {
      const originalRect = $sec[0].getBoundingClientRect();
      expect(originalRect.width).to.be.greaterThan(200);

      cy.wrap($sec).find('.section-drag-handle').first().then(($handle) => {
        const handleRect = $handle[0].getBoundingClientRect();
        const centerX = Math.round(originalRect.left + originalRect.width / 2);
        simulateDrag($handle, centerX, Math.round(handleRect.top + 40));

        // 1. Verify CVDragOverlay ghost rendered
        cy.get('[data-testid="drag-overlay-section"]').should('be.visible').then(($ghost) => {
          const ghostRect = $ghost[0].getBoundingClientRect();

          // Ghost width matches original section (1:1 scale fidelity)
          expect(Math.abs(ghostRect.width - originalRect.width)).to.be.lessThan(5);

          // Ghost should NOT have artificial rotation or scale transforms applied
          const ghostStyle = window.getComputedStyle($ghost[0]);
          const transform = ghostStyle.transform;
          if (transform && transform !== 'none') {
            expect(transform).to.not.include('matrix(0.');
          }

          // Ghost should NOT show duplicate pill badge
          cy.get('[data-testid="drag-overlay-section-title"]').should('not.be.visible');
        });

        // End drag
        endDrag(originalRect.left, originalRect.top + 40);
      });
    });
  });

  it('Drag Section over Sibling → Sibling sections never overlap or collide with placeholder', () => {
    cy.get('#experience, [data-section-id="experience"]').first().as('secExperience');
    cy.get('#projects, [data-section-id="projects"]').first().as('secProjects');

    cy.get('@secProjects').then(($proj) => {
      cy.get('@secExperience').then(($exp) => {
        const expRect = $exp[0].getBoundingClientRect();
        const projRect = $proj[0].getBoundingClientRect();

        cy.wrap($proj).find('.section-drag-handle').first().then(($handle) => {
          const centerX = Math.round(expRect.left + expRect.width / 2);
          const targetY = Math.round(expRect.top + expRect.height * 0.3);

          simulateDrag($handle, centerX, targetY);

          // Check placeholder and sibling sections
          cy.get('.is-dragging-placeholder').should('exist').then(($placeholder) => {
            const pRect = $placeholder[0].getBoundingClientRect();

            cy.get('@secExperience').then(($currExp) => {
              const currentExpRect = $currExp[0].getBoundingClientRect();

              // Sections must NOT physically overlap
              const doesOverlap = (
                pRect.top < currentExpRect.bottom - 5 &&
                pRect.bottom > currentExpRect.top + 5
              );
              expect(doesOverlap).to.be.false;

              // Placeholder is translucent (not competing with floating ghost)
              const pOpacity = parseFloat(window.getComputedStyle($placeholder[0]).opacity);
              expect(pOpacity).to.be.lessThan(0.6);
            });
          });

          endDrag(projRect.left, expRect.top + 20);
        });
      });
    });
  });

  it('Hover Pointer on Upper vs Lower Half → Correctly determines above vs below insertion position', () => {
    cy.get('#experience, [data-section-id="experience"]').first().as('secExperience');
    cy.get('#projects, [data-section-id="projects"]').first().as('secProjects');

    cy.get('@secProjects').find('.section-drag-handle').first().then(($handle) => {
      cy.get('@secExperience').then(($exp) => {
        const expRect = $exp[0].getBoundingClientRect();
        const targetX = Math.round(expRect.left + expRect.width / 2);

        // 1. Move to upper half (25%) of experience -> places projects ABOVE experience
        const targetYAbove = Math.round(expRect.top + expRect.height * 0.25);
        simulateDrag($handle, targetX, targetYAbove);

        // Retrying assertion: wait for React to reorder projects above experience
        cy.get('.is-dragging-placeholder').should(($placeholder) => {
          const pRect = $placeholder[0].getBoundingClientRect();
          const expEl = Cypress.$('#experience, [data-section-id="experience"]')[0];
          const currExpRect = expEl.getBoundingClientRect();
          expect(pRect.top).to.be.lessThan(currExpRect.top);
        });

        // 2. Move pointer into lower half (75%) of experience's updated position -> places projects back BELOW experience
        cy.get('@secExperience').then(($currExp) => {
          const currExpRect = $currExp[0].getBoundingClientRect();
          const targetYBelow = Math.round(currExpRect.top + currExpRect.height * 0.75);

          for (let s = 1; s <= 10; s++) {
            const moveY = Math.round(targetYAbove + ((targetYBelow - targetYAbove) * s) / 10);
            cy.document().trigger('pointermove', {
              pointerId: 1,
              pointerType: 'mouse',
              isPrimary: true,
              button: 0,
              buttons: 1,
              clientX: targetX,
              clientY: moveY,
              bubbles: true,
              cancelable: true,
            });
          }

          // Retrying assertion: wait for React to reorder projects back below experience
          cy.get('.is-dragging-placeholder').should(($placeholder) => {
            const pRect = $placeholder[0].getBoundingClientRect();
            const expEl = Cypress.$('#experience, [data-section-id="experience"]')[0];
            const finalExpRect = expEl.getBoundingClientRect();
            expect(pRect.top).to.be.greaterThan(finalExpRect.top - 10);
          });

          endDrag(currExpRect.left, currExpRect.bottom);
        });
      });
    });
  });

  it('Release Pointer → Drops cleanly into target position without layout disruption', () => {
    cy.get('#experience, [data-section-id="experience"]').first().as('secExperience');
    cy.get('#projects, [data-section-id="projects"]').first().as('secProjects');

    cy.get('@secProjects').find('.section-drag-handle').first().then(($handle) => {
      cy.get('@secExperience').then(($exp) => {
        const expRect = $exp[0].getBoundingClientRect();
        const centerX = Math.round(expRect.left + expRect.width / 2);
        const targetY = Math.round(expRect.top + 20);

        simulateDrag($handle, centerX, targetY);
        endDrag(centerX, targetY);

        // Ghost and placeholder must be gone
        cy.get('[data-testid="drag-overlay-section"]').should('not.exist');
        cy.get('.is-dragging-placeholder').should('not.exist');

        // Document layout is stable and rendered
        cy.get('#area-cv').should('be.visible');
        cy.get('#projects, [data-section-id="projects"]').should('be.visible');
        cy.get('#experience, [data-section-id="experience"]').should('be.visible');
      });
    });
  });
});
